 handlers.replacement=({id})=>{S.guard('finance');const o=S.order(id);modal('Approve a linked replacement','The replacement is a fulfilment cost. It has no new sale, and only the approved affected quantity is released.',select('item','Affected artwork',o.items.map(i=>[i.id,i.title+' · '+i.frame]))+field('qty','Quantity',1,'number')+field('cost','Estimated replacement cost (INR)',7900,'number')+check('reviewed','Existing refunds, replacement quantities and any dispute reviewed')+textarea('reason','Approval reason'),d=>{if(!d.reviewed)throw Error('Review other remedies before approving.');S.mutate(id,'Approve linked replacement',()=>{const i=S.item(o,d.item),qty=Number(d.qty),cost=Math.round(Number(d.cost)*100);if(!Number.isInteger(qty)||qty<1||qty>i.qty)throw Error('Choose an eligible purchased quantity.');if(!Number.isSafeInteger(cost)||cost<0)throw Error('Enter a valid non-negative cost.');const used=S.state.orders.filter(r=>r.replacement&&r.parent===id).flatMap(r=>r.items).filter(x=>x.parentItem===i.id).reduce((s,x)=>s+x.qty,0);if(used+qty>i.qty)throw Error('This item quantity already has a replacement.');if(o.refunds.filter(r=>r.item===i.id&&['Approved','Submitted','Unknown','Completed'].includes(r.status)).reduce((s,r)=>s+r.amount,0)>=i.price*i.qty)throw Error('This item already has a full refund remedy. Review before adding a replacement.');const newId=id+'-R'+(S.state.orders.filter(r=>r.parent===id).length+1),r=S.clone(o);Object.assign(r,{id:newId,parent:id,replacement:true,total:0,refunds:[],documents:[],changes:[],hold:false,cancelled:false,bankMatched:false,settlement:'Not applicable',dispute:'None',payment:'Captured',paymentRef:o.paymentRef,version:1,note:'Approved replacement: '+d.reason,costs:{production:cost,packaging:0,shipping:null,fees:0,remedy:0}});r.items=[{...S.clone(i),id:'LI-1',parentItem:i.id,qty,price:0,stage:1,reserved:false,consumed:false,started:null,rework:null,evidence:[],quality:'Not inspected',inspections:[],packing:null,parcel:null}];r.purchase=S.clone(r.items);S.state.orders.push(r);S.message(o,i,'Replacement approved '+newId);const c=S.state.cases.find(c=>c.order===id&&c.claim);if(c)c.claim.decision='Replacement approved · '+newId;});},'Approve replacement');};
