 forms['bank-match']=(d,{id})=>{S.guard('finance');if(!d.verified)throw Error('Check the actual receipt before matching.');const amount=Math.round(Number(d.amount)*100),o=S.order(id);if(!Number.isSafeInteger(amount)||amount<0)throw Error('Enter a valid bank amount.');if(expectedBank(o)===null)throw Error('Confirm captured payment and provider fees before matching a bank receipt.');modal('Record bank comparison?','A mismatched amount creates an attention task and remains unmatched.',facts([['Expected',money(expectedBank(o))],['Recorded receipt',money(amount)],['Reference',esc(d.reference)]]),()=>S.mutate(id,'Compare bank receipt',()=>{if(expectedBank(o)===null)throw Error('The settlement basis is incomplete. Confirm payment and fees first.');o.bankMatched=amount===expectedBank(o);o.bankReference=d.reference;o.bankSource=d.source;o.bankAmount=amount;if(!o.bankMatched)S.task(o,'Settlement amount differs','orders/settlement?id='+id);else S.resolveTask(id,'Settlement');}),'Record comparison');};
