 handlers['document-create']=({id})=>modal('Prepare a sample document','Purchased lines are copied into an immutable sample document. Tax treatment is explicitly unconfigured.',select('type','Document type',['Invoice','Credit note'])+textarea('reason','Issue reason','Sample issue at the configured approval point'),d=>{S.guard('finance');S.mutate(id,'Prepare '+d.type,()=>{const o=S.order(id);if(o.payment!=='Captured')throw Error('Confirm captured payment first.');if(d.type==='Invoice'&&o.documents.some(x=>x.type==='Invoice'&&x.status==='Issued'))throw Error('An issued invoice exists. Use correction/void history.');const credited=o.documents.filter(x=>x.type==='Credit note'&&x.status==='Issued').reduce((n,x)=>n+x.amount,0),credit=completed(o)-credited;if(d.type==='Credit note'&&credit<=0)throw Error('No confirmed refund remains without a credit note. Reuse or correct the existing document.');o.documents.push({id:(d.type==='Invoice'?'INV':'CN')+'-DEMO-'+id+'-'+(o.documents.length+1),type:d.type,amount:d.type==='Invoice'?o.total:credit,lines:d.type==='Invoice'?S.clone(o.purchase):[{title:'Confirmed refund adjustment',frame:'Affected items in linked refund records',qty:1,price:credit}],address:o.purchaseAddress,status:'Issued',at:S.now(),reason:d.reason});});},'Issue sample');
 handlers['document-correct']=({id,doc})=>modal('Correct or void the sample document','The issued content remains unchanged. Its correction links to a new record.',select('operation','Action',['Create corrected version','Void document'])+textarea('reason','Correction reason'),d=>{S.guard('finance');S.mutate(id,'Document correction',()=>{const o=S.order(id),old=o.documents.find(x=>x.id===doc);if(old.status!=='Issued')throw Error('This document already has a correction or void record.');old.status=d.operation==='Void document'?'Void':'Superseded';old.correctionReason=d.reason;if(d.operation==='Create corrected version')o.documents.push({...S.clone(old),id:old.type.slice(0,3).toUpperCase()+'-DEMO-'+id+'-'+(o.documents.length+1),status:'Issued',corrects:old.id,reason:d.reason,at:S.now()});});},'Record correction');
 handlers['document-download']=({id,doc})=>{S.guard('finance');const o=S.order(id),d=o.documents.find(x=>x.id===doc);download(d.id+'.html',`<!doctype html><html lang="en"><meta charset="utf-8"><title>${esc(d.id)}</title><body style="font:15px/1.6 system-ui;max-width:760px;margin:60px auto;padding:30px;border:1px solid #ccc"><p style="color:#9b403b">SAMPLE — NOT A TAX DOCUMENT</p><h1>Aalishaan Studio</h1><h2>${esc(d.type)} ${esc(d.id)}</h2><p>Source order: ${esc(id)} · ${esc(d.status)}</p><p>Purchased address: ${esc(d.address)}</p><table style="width:100%;text-align:left"><tr><th>Artwork</th><th>Frame / qty</th><th>Line amount</th></tr>${d.lines.map(i=>`<tr><td>${esc(i.title)}</td><td>${esc(i.frame)} / ${i.qty}</td><td>${money(i.price*i.qty)}</td></tr>`).join('')}</table><h3>Document amount ${money(d.amount)} · INR</h3><p>Tax classification and seller legal details: unconfigured.</p><p>${esc(d.reason)}${d.corrects?' · Corrects '+esc(d.corrects):''}</p><p>No live transaction or legal invoice is created by this prototype.</p></body></html>`,'text/html');};
