 handlers['case-new']=({customer:cid,order:orderId}={})=>{S.guard('support');const options=S.state.orders.filter(o=>!cid||o.customer===cid);modal('Capture a customer request','Record the actual source. Pre-purchase enquiries can be captured without inventing an order.',select('order','Original order (optional)',[['','Pre-purchase enquiry — no order'],...options.map(o=>[o.id,o.id+' · '+customer(o).name])],orderId||'')+select('customer','Enquiry contact',[['','New enquiry contact'],...S.state.customers.map(c=>[c.id,c.name])],cid||'')+field('contactName','New enquiry contact name','','text','Needed only for a new contact without an order.',false)+field('contactEmail','New enquiry contact email','','email','Use fictional details in this prototype.',false)+field('subject','Subject')+select('source','Actual source',['Email · manually captured','Phone · manually captured','WhatsApp · manually captured'])+select('owner','Owner',['Rahul','Khalid'])+select('priority','Priority',['Normal','High'])+textarea('note','Customer request'),d=>{S.mutate('CASES','Capture customer request',()=>{const o=d.order?S.order(d.order):null;let person=o?customer(o):S.state.customers.find(c=>c.id===d.customer);if(!person){if(!d.contactName.trim()||!d.contactEmail.trim())throw Error('Add an enquiry contact name and email, or select an existing contact.');person={id:'C-ENQ-'+(S.state.customers.length+1),name:d.contactName.trim(),email:d.contactEmail.trim(),phone:'Not provided',notes:'Pre-purchase enquiry contact',verified:false,linked:[],preferences:{email:'Unknown',whatsapp:'Unknown',sms:'Unknown'},consent:[],privacy:null};S.state.customers.push(person);}const id='CS-'+(1000+S.state.cases.length+1)+'-NEW',c={id,order:o?.id||null,customer:person.id,subject:d.subject,source:d.source,owner:d.owner,priority:d.priority,status:'Open',verified:false,notes:[{text:d.note,at:S.now(),actor:S.names[S.state.role]}],replies:[],due:'2026-09-13',type:'Enquiry'};S.state.cases.push(c);S.syncCaseTask(c);});},'Create request');};
 screens['support/case']=()=>{const c=getCase();if(!c)return heading('Customer request','No case has been captured for this order.',empty('Start the conversation record','Capture the actual source and assign a named owner.','support','Open requests')+actions(button('case-new','Capture a request')));const o=c.order?S.order(c.order):null,person=S.state.customers.find(x=>x.id===c.customer);return heading(c.subject,c.id+' · '+c.source,link('support','← Requests')+grid(panel('Conversation',c.notes.map(n=>`<div class="notice"><h2>Private note · ${esc(n.actor)}</h2><p>${esc(n.text)}</p></div>`).join('')+c.replies.map(r=>`<div class="notice"><h2>${esc(r.status)} · ${esc(r.source)}</h2><p>${esc(r.body)}</p><p class="small">${esc(r.at)} · ${esc(r.template)}</p></div>`).join('')+(!c.notes.length&&!c.replies.length?'<p class="small">No response is recorded. Capture a private note or use an approved reply.</p>':'')+actions(button('case-note','Add private note',{id:c.id},'button secondary'),button('case-reply','Use saved reply',{id:c.id})))+panel('Resolution history',history(c.id)),panel('Original records',facts([['Customer',link('customers/profile?id='+c.customer,person.name)],['Order',o?link('orders/record?id='+c.order,c.order):'Pre-purchase enquiry'],['Owner',esc(c.owner)],['Priority',esc(c.priority)],['First response / resolution due',c.due+' / sample next working day'],['State',pill(c.status)],['Sensitive disclosure check',c.verified?'Identity checked':'Identity check needed']])+actions(button('case-manage','Manage request',{id:c.id},'button secondary')))+(o?notice('Remedies stay with the order','The owner reviews refunds and replacements here using the original order and payment records. '+link(orderUrl('orders/refund',o),'Open order remedies')):'')+actions(c.claim?link('support/claim?id='+c.id,'Review damage evidence','button secondary'):'')));};
 handlers['case-note']=({id})=>modal('Add a private note','This stays with the sample case and its original order.',textarea('text','Private note'),d=>{S.guard('support');S.mutate(id,'Private support note',()=>S.state.cases.find(c=>c.id===id).notes.push({text:d.text,at:S.now(),actor:S.names[S.state.role]}));},'Save private note');
 handlers['case-manage']=({id})=>{const c=S.state.cases.find(c=>c.id===id);modal('Manage request '+id,'A resolved case can reopen without losing its conversation.',select('owner','Owner',['Rahul','Khalid'],c.owner)+select('priority','Priority',['Normal','High'],c.priority)+field('due','Follow-up date',c.due,'date')+select('status','Status',['Open','Waiting for customer','Waiting for studio','Resolved','Reopened'],c.status)+check('identity','Identity checked for sensitive support',c.verified)+textarea('reason','Outcome or next action'),d=>{S.guard('support');S.mutate(id,'Case ownership / state',()=>{Object.assign(c,{owner:d.owner,priority:d.priority,due:d.due,status:d.status,verified:Boolean(d.identity)});c.notes.push({text:d.reason,at:S.now(),actor:S.names[S.state.role]});S.syncCaseTask(c);},d.reason);},'Save request');};
 handlers['case-reply']=({id})=>{S.guard('support');const c=S.state.cases.find(c=>c.id===id),reply=S.state.savedReplies.find(r=>r.status==='Approved sample');if(!reply){modal('No approved saved reply','An owner must review a draft reply before it can be used.',link('support/replies','Open saved replies'),()=>{location.hash='support/replies';},'Review reply library');return;}modal('Prepare an approved reply','Use the existing customer channel, then honestly record the known send result. This prototype sends nothing.',select('template','Saved reply',S.state.savedReplies.filter(r=>r.status==='Approved sample').map(r=>[r.id,r.title]),reply?.id)+textarea('body','Reply text',reply?.body||'')+select('status','Actual sample outcome',['Draft — not sent','Manually sent through original channel','Send failed'])+check('identity','Identity checked before sensitive order details'),d=>{if(d.status!=='Draft — not sent'&&!d.identity)throw Error('Check identity before recording a sensitive reply.');S.mutate(id,'Support reply record',()=>{const t=S.state.savedReplies.find(r=>r.id===d.template);c.replies.push({body:d.body,status:d.status,source:c.source,template:t.id+'-v'+t.version,at:S.now()});c.verified=c.verified||Boolean(d.identity);if(d.status==='Manually sent through original channel')c.firstResponseAt=c.firstResponseAt||S.now();});},'Record reply outcome');const form=document.querySelector('#modal-form');form.elements.template.onchange=()=>form.elements.body.value=S.state.savedReplies.find(r=>r.id===form.elements.template.value).body;};
 screens['support/replies']=()=>heading('Saved replies','Approved wording with versions; review edits before use.',table('Reply library',['Reply','Current wording','Version / approval','Edit'],S.state.savedReplies.map(r=>[esc(r.title),esc(r.body),pill(r.status)+'<small>v'+r.version+'</small>',button('reply-edit','Edit reply',{id:r.id},'button secondary')])));
 handlers['reply-edit']=({id})=>{S.guard('support');const r=S.state.savedReplies.find(r=>r.id===id);modal('Edit saved reply','A revision remains a draft until an owner approves its sample wording.',field('title','Reply title',r.title)+textarea('body','Wording',r.body)+(S.state.role==='owner'?check('approve','Approve this sample wording'):''),d=>S.mutate(id,'Saved reply revision',()=>Object.assign(r,{title:d.title,body:d.body,version:r.version+1,status:d.approve&&S.state.role==='owner'?'Approved sample':'Draft'})),'Save reply revision');};
 screens['support/claims']=()=>heading('Returns & damage','Customer evidence, studio evidence and a considered decision.',table('Claims',['Claim / order','Reason','Customer remedy','Courier compensation','Open'],S.state.cases.filter(c=>c.claim).map(c=>[esc(c.id)+`<small>${c.order}</small>`,esc(c.subject),esc(c.claim.decision),esc(c.claim.compensation),link('support/claim?id='+c.id,'Review claim')])));
 screens['support/claim']=()=>{const c=getCase();if(!c?.claim)return heading('Damage claim','No damage case exists for this record.',link('support/claims','Return to claims'));const o=S.order(c.order);return heading('Damage claim · '+c.id,'Review the evidence and purchased policy before recommending a remedy.',link('support/case?id='+c.id,'← Original customer request')+grid(panel('Evidence, side by side',`<div class="two-col">${c.claim.evidence.map(x=>`<div class="evidence"><strong>${esc(x)}</strong><p>Synthetic evidence reference; no real customer file is present.</p></div>`).join('')}</div>`+notice('No unboxing video? Review the available evidence.','Missing video alone does not automatically reject this claim. Follow the approved policy and document the reason.'))+panel('Review decision',form('claim',select('decision','Recommended outcome',['Awaiting review','Request relevant evidence','Recommend replacement','Recommend partial refund','Approve return review','Decline after policy review'],c.claim.decision)+check('identity','Identity and affected purchased item checked')+textarea('reason','Policy review, evidence and reason'),'Record recommendation',{id:c.id})),panel('Case context',facts([['Customer',esc(customer(o).name)],['Original order',link(orderUrl('orders/record',o),o.id)],['Policy',esc(o.policy)],['Owner / reply due',esc(c.owner)+' / '+c.due],['Customer remedy',esc(c.claim.decision)],['Return',esc(c.claim.returnStatus)],['Courier recovery',esc(c.claim.compensation)]]))+actions(link(orderUrl('orders/refund',o),'Review authorised remedy','button'),link('support/return?id='+c.id,'Track return','button secondary'),link('support/compensation?id='+c.id,'Courier compensation','button secondary'))));};
 forms.claim=(d,{id})=>{S.guard('support');if(!d.identity)throw Error('Verify identity and affected item before a remedy recommendation.');commit(id,'Damage evidence recommendation',()=>{const c=S.state.cases.find(c=>c.id===id);c.verified=true;c.claim.decision=d.decision;c.claim.reason=d.reason;c.notes.push({text:d.reason,actor:S.names[S.state.role],at:S.now()});},d.reason);};
 screens['support/return']=()=>{const c=getCase();if(c&&!c.order)return heading('Return record','Link the original purchase before recording a return.',link('support/case?id='+c.id,'Open original enquiry'));if(!c)return heading('Return record','A return needs an owned case linked to the original order.',actions(button('case-new','Capture the return request')));const claim=c.claim||{returnStatus:'Not requested',inspection:'Not inspected'};return heading('Return · '+c.id,'Record actual receipt before inspection, recovery, rework or disposal.',panel('Return movement',facts([['Order',link('orders/record?id='+c.order,c.order)],['State',pill(claim.returnStatus)],['Inspection',esc(claim.inspection)],['Physical evidence',esc(claim.returnEvidence)||'Not recorded']]))+(claim.returnHistory?.length?table('Return movement history',['Event','Evidence / reason','Recorded by'],claim.returnHistory.map(h=>[esc(h.status),esc(h.evidence),esc(h.actor)+'<small>'+esc(h.at)+'</small>'])):'')+panel('Record the next actual event',form('return',select('status','Return event',['Pickup requested','In return transit','Received at studio','Inspected — recoverable','Inspected — rework','Inspected — dispose'])+textarea('evidence','Physical evidence / inspection and reason'),'Record return event',{id:c.id})));};
 forms.return=(d,{id})=>{S.guard('support');commit(id,'Return movement / inspection',()=>{const c=S.state.cases.find(c=>c.id===id);c.claim||={evidence:[],decision:'Return review',compensation:'Not submitted',returnStatus:'Not requested',inspection:'Not inspected'};const phases=['Not requested','Pickup requested','In return transit','Received at studio'];const current=c.claim.returnStatus,inspected=current.startsWith('Inspected');if(inspected||current==='Received at studio'&&!d.status.startsWith('Inspected')||phases.includes(d.status)&&phases.indexOf(d.status)<=phases.indexOf(current))throw Error('An earlier or repeated return event cannot replace the recorded receipt or inspection. Review a correction with the owner.');if(d.status.startsWith('Inspected')&&current!=='Received at studio')throw Error('Record actual studio receipt before inspection and recovery.');if(d.status==='Received at studio'&&current==='Not requested')throw Error('Record the return request and transport history first.');c.claim.returnHistory||=[];c.claim.returnHistory.push({status:d.status,evidence:d.evidence,at:S.now(),actor:S.names[S.state.role]});c.claim.returnStatus=d.status;c.claim.returnEvidence=d.evidence;if(d.status.startsWith('Inspected'))c.claim.inspection=d.status;},d.evidence);};
 screens['support/compensation']=()=>{const c=getCase();if(!c?.claim)throw Error('No courier compensation case is linked.');return heading('Courier compensation · '+c.id,'Track recovery independently of the customer’s remedy.',panel('Separate claim record',facts([['Customer remedy',esc(c.claim.decision)],['Courier claim',pill(c.claim.compensation)],['Protection / terms','Unconfirmed — no assumed coverage'],['Recovered amount',money(c.claim.recovered)],['Owner / deadline',esc(c.owner)+' / confirm provider claim deadline']]))+panel('Record provider outcome',form('compensation',select('status','Compensation outcome',['Not submitted','Submitted','Under review','Approved, awaiting recovery','Recovered','Declined'])+field('amount','Recovered amount (INR)',0,'number')+textarea('reference','Provider reference, evidence and reason'),'Save compensation record',{id:c.id})));};
 forms.compensation=(d,{id})=>{S.guard('support');const amount=Math.round(Number(d.amount)*100);if(!Number.isSafeInteger(amount)||amount<0)throw Error('Enter a valid non-negative recovery amount.');commit(id,'Courier compensation outcome',()=>{const c=S.state.cases.find(c=>c.id===id);c.claim.compensation=d.status;c.claim.recovered=d.status==='Recovered'?amount:null;c.claim.reference=d.reference;});};
 screens['support/messages']=()=>{const rows=S.state.messages.filter(m=>!A.params.get('order')||m.order===A.params.get('order'));return heading('Message history','Four normal milestones, plus relevant exceptions and remedies.',notice('Known status, without guessing','Provider acceptance means the service accepted the message. It does not mean the customer read it. All sends here are simulations.')+scenario()+queue(table('Transactional updates',['Event / order','Recipient / item','Template','Known state / attempts','Next action'],rows.map(m=>[esc(m.kind)+`<small>${m.order}</small>`,esc(m.recipient)+`<small>${esc(m.item)}</small>`,esc(m.template),pill(m.status,['Failed','Unknown'].includes(m.status)?'warn':'neutral')+`<small>${m.attempts} attempts</small>`,button('message','Review outcome',{id:m.id},'button secondary')]))));};
 handlers.message=({id})=>{S.guard('support');const m=S.state.messages.find(m=>m.id===id);modal('Review '+m.kind.toLowerCase(),'Verify uncertain sends before retry or fallback. The order and parcel statuses stay unchanged.',facts([['Original order',m.order],['Item context',m.item],['Known state',esc(m.status)],['Recipient',esc(m.recipient)]])+select('outcome','Verified sample result',['Provider accepted','Confirmed not sent','Unknown','Failed','Manually sent','Suppressed'])+check('verified','I checked the existing send outcome before this action')+textarea('reason','Verification or fallback reference'),d=>{if(!d.verified)throw Error('Check the existing provider outcome first.');if(m.status==='Provider accepted'&&d.outcome==='Manually sent')throw Error('This send is already accepted. Avoid a duplicate manual message.');if(m.status==='Unknown'&&d.outcome==='Manually sent')throw Error('Resolve the unknown outcome as accepted or confirmed not sent before manual fallback.');S.mutate(id,'Message verification / fallback',()=>{m.status=d.outcome;m.reference=d.reason;m.checkedAt=S.now();if(d.outcome==='Manually sent')m.attempts++;});},'Record known outcome');};
